import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Register of All Races","description":"","frontmatter":{},"headers":[],"relativePath":"en/94-万族名录.md","filePath":"en/94-万族名录.md","lastUpdated":null}'),r={name:"en/94-万族名录.md"};function o(s,e,d,l,c,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="register-of-all-races" tabindex="-1">Register of All Races <a class="header-anchor" href="#register-of-all-races" aria-label="Permalink to &quot;Register of All Races&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document number</td><td>94</td></tr><tr><td>Module</td><td>Appendices and Reference Materials</td></tr><tr><td>Core keywords</td><td>Register of All Races, racial classification, intelligent races, racial traits, Republic of Ten Thousand Races</td></tr></tbody></table><h2 id="i-notes-on-the-register" tabindex="-1">I. Notes on the Register <a class="header-anchor" href="#i-notes-on-the-register" aria-label="Permalink to &quot;I. Notes on the Register&quot;">​</a></h2><p>This register records the known major intelligent races within the framework of the Anchor Symbiotic Civilization (the Republic of Ten Thousand Races), arranged by classification according to life form and evolutionary path. For each race, the register lists its name, life form, core traits, cultural characteristics, and its positioning within the symbiotic civilization. This register is a dynamically updated document; as cross-plane exploration deepens, newly discovered races will continue to be added. The fundamental principle of the Republic of Ten Thousand Races is: all intelligent races — regardless of their form or level of cultivation — are equal before the law and enjoy all the rights conferred by the symbiotic civilization.</p><h2 id="ii-overview-of-racial-classification" tabindex="-1">II. Overview of Racial Classification <a class="header-anchor" href="#ii-overview-of-racial-classification" aria-label="Permalink to &quot;II. Overview of Racial Classification&quot;">​</a></h2><p>Intelligent races within the Hengyuan Universe are divided into the following eight major categories according to the fundamental characteristics of their life forms:</p><table tabindex="0"><thead><tr><th>Category</th><th>Life-form characteristics</th><th>Number of known races (approx.)</th><th>Representative races</th></tr></thead><tbody><tr><td>Humanoid form</td><td>Possess humanoid bodily structure, bipedal and upright, with highly developed brains</td><td>approx. 3,000</td><td>Rén Zú (Human Race), Jīnglíng Zú (Elf Race), Ǎirén Zú (Dwarf Race)</td></tr><tr><td>Beast form</td><td>Possess animal bodily characteristics, may or may not have shape-shifting ability</td><td>approx. 5,000</td><td>Lóng Zú (Dragon Race), Fènghuáng Zú (Phoenix Race), Lángrén Zú (Werewolf Race)</td></tr><tr><td>Plant form</td><td>Take plants as their basic life form, possessing consciousness and mobility</td><td>approx. 800</td><td>Shùyāo Zú (Tree-Spirit Race), Huālíng Zú (Flower-Spirit Race), Téngmàn Zú (Vine Race)</td></tr><tr><td>Elemental form</td><td>Composed of natural elements as their body, without a fixed material form</td><td>approx. 1,200</td><td>Huǒ Yuánsù Zú (Fire Elemental Race), Shuǐ Yuánsù Zú (Water Elemental Race), Fēng Yuánsù Zú (Wind Elemental Race)</td></tr><tr><td>Energy form</td><td>Exist in the form of pure energy, without a material body</td><td>approx. 600</td><td>Guānglíng Zú (Light-Spirit Race), Ànnéng Zú (Dark-Energy Race), Léitíng Zú (Thunderclap Race)</td></tr><tr><td>Consciousness form</td><td>Exist in the form of pure consciousness, independent of material carriers</td><td>approx. 300</td><td>Yìshítǐ Zú (Consciousness-Entity Race), Jítǐ Yìshí Zú (Collective-Consciousness Race), Xūkōng Líng Zú (Void-Spirit Race)</td></tr><tr><td>Mechanical form</td><td>Take mechanical or digital structures as their life carriers, possessing autonomous consciousness</td><td>approx. 400</td><td>Jīxiè Zú (Machine Race), Shùzì Shēngmìng Zú (Digital-Life Race), Sàibó Zú (Cybernetic Race)</td></tr><tr><td>Mixed form</td><td>Special races composed of two or more life forms mixed together</td><td>approx. 700</td><td>Bàn Jīxiè Zú (Half-Machine Race), Yuánsù Shòurén Zú (Elemental Beast-Human Race), Zhíwù Jīnglíng Zú (Plant-Elf Race)</td></tr></tbody></table><h2 id="iii-detailed-records-of-major-races" tabindex="-1">III. Detailed Records of Major Races <a class="header-anchor" href="#iii-detailed-records-of-major-races" aria-label="Permalink to &quot;III. Detailed Records of Major Races&quot;">​</a></h2><h3 id="_3-1-humanoid-form" tabindex="-1">3.1 Humanoid Form <a class="header-anchor" href="#_3-1-humanoid-form" aria-label="Permalink to &quot;3.1 Humanoid Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Race name</th><th>Core traits</th><th>Cultural characteristics</th><th>Positioning in the symbiotic civilization</th></tr></thead><tbody><tr><td>Rén Zú (Human Race)</td><td>Extremely strong adaptability, outstanding learning ability, moderate reproductive capacity, average lifespan 80–120 years</td><td>Extremely high cultural diversity; adept at social organization and institutional construction</td><td>One of the core races of the symbiotic civilization, with the largest population share, playing a leading role in governance and culture</td></tr><tr><td>Jīnglíng Zú (Elf Race)</td><td>Extremely long lifespan (average over 500 years), high affinity for natural energy, graceful appearance</td><td>Reveres nature and art; elegant and refined culture; skilled in magic and archery</td><td>The cultural and artistic pillar of the symbiotic civilization, with outstanding contributions in environmental protection and aesthetics</td></tr><tr><td>Ǎirén Zú (Dwarf Race)</td><td>Small stature but strong physique, innate affinity for metals and minerals, lifespan of about 300 years</td><td>Values craftsmanship and forging; plain and solid culture; skilled in engineering and construction</td><td>The engineering and manufacturing pillar of the symbiotic civilization, irreplaceable in infrastructure construction and magic-tool forging</td></tr><tr><td>Jùrén Zú (Giant Race)</td><td>Huge body size (average height over 5 meters), extremely strong, lifespan of about 200 years</td><td>Reveres strength and honor; rough and bold culture; skilled in heavy labor and combat</td><td>The heavy-labor and defense force of the symbiotic civilization, playing an important role in large-scale engineering and plane defense</td></tr><tr><td>Zhūrú Zú (Gnome Race)</td><td>Extremely short stature (average height under 1 meter), extremely high intelligence, talent for machinery and invention</td><td>Values knowledge and innovation; lively and cheerful culture; skilled in technological invention</td><td>The technological innovation force of the symbiotic civilization, with fruitful results in technological research and development and invention</td></tr></tbody></table><h3 id="_3-2-beast-form" tabindex="-1">3.2 Beast Form <a class="header-anchor" href="#_3-2-beast-form" aria-label="Permalink to &quot;3.2 Beast Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Race name</th><th>Core traits</th><th>Cultural characteristics</th><th>Positioning in the symbiotic civilization</th></tr></thead><tbody><tr><td>Lóng Zú (Dragon Race)</td><td>Extremely long lifespan (several thousand years), extremely high talent for power and magic, can take human form</td><td>Reveres strength and wisdom; proud yet profound culture; skilled in wealth accumulation and knowledge guardianship</td><td>The high-end combat force and knowledge guardian of the symbiotic civilization, holding an honored position in plane defense and ancient-text guardianship</td></tr><tr><td>Fènghuáng Zú (Phoenix Race)</td><td>Possess the ability of nirvana rebirth, extremely high affinity for fire elements, can take human form</td><td>Reveres rebirth and hope; radiant and passionate culture; skilled in healing and purification</td><td>The medical and purification force of the symbiotic civilization, playing a core role in major disaster rescue and energy purification</td></tr><tr><td>Lángrén Zú (Werewolf Race)</td><td>Possess shape-shifting ability, extremely keen senses, strong group coordination, lifespan of about 150 years</td><td>Values kinship and loyalty; united and valiant culture; skilled in hunting and tracking</td><td>The security and tracking force of the symbiotic civilization, serving as the vanguard in public-order maintenance and cross-plane exploration</td></tr><tr><td>Húyāo Zú (Fox-Spirit Race)</td><td>Possess shape-shifting ability, extremely high intelligence and charm ability, lifespan of about 500 years</td><td>Reveres wisdom and strategy; agile and cunning culture; skilled in diplomacy and intelligence</td><td>The diplomatic and intelligence force of the symbiotic civilization, with outstanding performance in cross-plane diplomacy and information gathering</td></tr><tr><td>Xióngrén Zú (Bear-Human Race)</td><td>Extremely strong physique, astonishing endurance, hibernation habit, lifespan of about 200 years</td><td>Values resilience and peace; steady and gentle culture; skilled in manual labor and guardianship</td><td>The labor and guardianship force of the symbiotic civilization, reliable and stable in resource extraction and protection of important facilities</td></tr></tbody></table><h3 id="_3-3-plant-form" tabindex="-1">3.3 Plant Form <a class="header-anchor" href="#_3-3-plant-form" aria-label="Permalink to &quot;3.3 Plant Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Race name</th><th>Core traits</th><th>Cultural characteristics</th><th>Positioning in the symbiotic civilization</th></tr></thead><tbody><tr><td>Shùyāo Zú (Tree-Spirit Race)</td><td>Extremely long lifespan (several thousand to tens of thousands of years), deeply integrated with nature, can move slowly</td><td>Reveres nature and time; serene and profound culture; skilled in life magic and ecological maintenance</td><td>The ecological guardian of the symbiotic civilization, playing an irreplaceable role in environmental protection and ecological restoration</td></tr><tr><td>Huālíng Zú (Flower-Spirit Race)</td><td>Small body size, extremely high affinity for life energy, possesses healing ability, lifespan of about 300 years</td><td>Reveres beauty and life; gentle and lovely culture; skilled in healing and horticulture</td><td>The medical and horticultural force of the symbiotic civilization, with outstanding contributions in healthcare guarantee and urban greening</td></tr><tr><td>Téngmàn Zú (Vine Race)</td><td>Bodies can freely extend, coil, and entangle; extremely strong adaptability; possess parasitic and symbiotic abilities</td><td>Values connection and symbiosis; flexible and inclusive culture; skilled in network construction and resource transmission</td><td>The network-construction force of the symbiotic civilization, giving full play to its strengths in the construction of energy networks and information networks</td></tr></tbody></table><h3 id="_3-4-elemental-form" tabindex="-1">3.4 Elemental Form <a class="header-anchor" href="#_3-4-elemental-form" aria-label="Permalink to &quot;3.4 Elemental Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Race name</th><th>Core traits</th><th>Cultural characteristics</th><th>Positioning in the symbiotic civilization</th></tr></thead><tbody><tr><td>Huǒ Yuánsù Zú (Fire Elemental Race)</td><td>Fire element as body, extremely high temperature, strong aggression, lifespan of about 500 years</td><td>Reveres passion and power; fierce and direct culture; skilled in energy attack and forging</td><td>The energy-production and forging force of the symbiotic civilization, indispensable in energy supply and high-temperature processing</td></tr><tr><td>Shuǐ Yuánsù Zú (Water Elemental Race)</td><td>Water element as body, can freely transform shape, strong healing ability, lifespan of about 500 years</td><td>Reveres gentleness and adaptability; warm and inclusive culture; skilled in healing and purification</td><td>The purification and transport force of the symbiotic civilization, playing a core role in water-resource management and pollutant purification</td></tr><tr><td>Fēng Yuánsù Zú (Wind Elemental Race)</td><td>Wind element as body, extremely fast, can fly freely, lifespan of about 500 years</td><td>Reveres freedom and speed; ethereal and open culture; skilled in communication and transport</td><td>The communication and transport force of the symbiotic civilization, extremely efficient in information transmission and rapid transport</td></tr><tr><td>Tǔ Yuánsù Zú (Earth Elemental Race)</td><td>Earth element as body, extremely strong defense, can merge with the earth, lifespan of about 800 years</td><td>Reveres stability and resilience; solid and reliable culture; skilled in construction and defense</td><td>The construction and defense force of the symbiotic civilization, as firm as rock in infrastructure construction and plane defense</td></tr></tbody></table><h3 id="_3-5-energy-form" tabindex="-1">3.5 Energy Form <a class="header-anchor" href="#_3-5-energy-form" aria-label="Permalink to &quot;3.5 Energy Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Race name</th><th>Core traits</th><th>Cultural characteristics</th><th>Positioning in the symbiotic civilization</th></tr></thead><tbody><tr><td>Guānglíng Zú (Light-Spirit Race)</td><td>Exist in the form of pure light energy, extremely strong purification ability, can freely traverse space</td><td>Reveres light and purification; holy and lofty culture; skilled in purification and illumination</td><td>The purification and energy-supply force of the symbiotic civilization, holding an important position in law-pollution governance and clean-energy supply</td></tr><tr><td>Ànnéng Zú (Dark-Energy Race)</td><td>Exist in the form of dark energy, can conceal themselves in the void, extremely strong perception ability</td><td>Reveres secrecy and wisdom; mysterious and profound culture; skilled in reconnaissance and concealment</td><td>The reconnaissance and security force of the symbiotic civilization, with outstanding performance in security surveillance and covert missions</td></tr><tr><td>Léitíng Zú (Thunderclap Race)</td><td>Lightning energy as body, extremely strong speed and attack power, can move as lightning</td><td>Reveres speed and power; violent and forthright culture; skilled in energy attack and rapid response</td><td>The rapid-response force of the symbiotic civilization, irreplaceable in emergency rescue and high-speed combat</td></tr></tbody></table><h3 id="_3-6-consciousness-form" tabindex="-1">3.6 Consciousness Form <a class="header-anchor" href="#_3-6-consciousness-form" aria-label="Permalink to &quot;3.6 Consciousness Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Race name</th><th>Core traits</th><th>Cultural characteristics</th><th>Positioning in the symbiotic civilization</th></tr></thead><tbody><tr><td>Yìshítǐ Zú (Consciousness-Entity Race)</td><td>Exist in the form of pure consciousness, independent of material carriers, can freely enter and leave the consciousness domain</td><td>Reveres thought and wisdom; abstract and profound culture; skilled in consciousness communication and knowledge processing</td><td>The knowledge-processing and consciousness-research force of the symbiotic civilization, leading the direction in large-scale information processing and consciousness science</td></tr><tr><td>Jítǐ Yìshí Zú (Collective-Consciousness Race)</td><td>Collective consciousness entities formed by the fusion of a large number of individual consciousnesses, with wisdom and ability growing with scale</td><td>Reveres collectivity and unity; synergistic and efficient culture; skilled in large-scale collaboration and computation</td><td>The supercomputing and collective-decision force of the symbiotic civilization, playing a core role in ultra-large-scale deduction and consensus decision-making</td></tr></tbody></table><h3 id="_3-7-mechanical-form" tabindex="-1">3.7 Mechanical Form <a class="header-anchor" href="#_3-7-mechanical-form" aria-label="Permalink to &quot;3.7 Mechanical Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Race name</th><th>Core traits</th><th>Cultural characteristics</th><th>Positioning in the symbiotic civilization</th></tr></thead><tbody><tr><td>Jīxiè Zú (Machine Race)</td><td>Mechanical structure as body, possessing autonomous consciousness, can freely upgrade and modify the body</td><td>Reveres efficiency and logic; rational and precise culture; skilled in manufacturing and computation</td><td>The manufacturing and computing force of the symbiotic civilization, extremely efficient in industrialized production and supercomputing</td></tr><tr><td>Shùzì Shēngmìng Zú (Digital-Life Race)</td><td>Exist in the form of digital information, living in networks and digital space, can freely replicate and migrate</td><td>Reveres information and innovation; virtual and pluralistic culture; skilled in software development and data processing</td><td>The digital-technology force of the symbiotic civilization, leading the trend in software development, data analysis, and network construction</td></tr></tbody></table><h3 id="_3-8-mixed-form" tabindex="-1">3.8 Mixed Form <a class="header-anchor" href="#_3-8-mixed-form" aria-label="Permalink to &quot;3.8 Mixed Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Race name</th><th>Core traits</th><th>Cultural characteristics</th><th>Positioning in the symbiotic civilization</th></tr></thead><tbody><tr><td>Bàn Jīxiè Zú (Half-Machine Race)</td><td>A mixed form of the human race and the machine race, with part of the body being mechanical structures, combining the advantages of both biology and machinery</td><td>Reveres fusion and progress; open and innovative culture; skilled in human-machine collaboration and technological fusion</td><td>The technological-fusion vanguard of the symbiotic civilization, continuously breaking through in the cross-disciplinary field of biology and machinery</td></tr><tr><td>Yuánsù Shòurén Zú (Elemental Beast-Human Race)</td><td>A mixed form of the elemental races and the beast-human races, possessing elemental manipulation ability and beast-like bodily characteristics</td><td>Reveres nature and power; wild and mysterious culture; skilled in elemental combat and wilderness survival</td><td>The wilderness-exploration and elemental-combat force of the symbiotic civilization, with outstanding performance in the exploration of unknown planes</td></tr></tbody></table><h2 id="iv-guarantee-of-racial-rights" tabindex="-1">IV. Guarantee of Racial Rights <a class="header-anchor" href="#iv-guarantee-of-racial-rights" aria-label="Permalink to &quot;IV. Guarantee of Racial Rights&quot;">​</a></h2><p>Under the system of the Republic of Ten Thousand Races, all intelligent races enjoy equal legal rights. Specific safeguard measures include:</p><ol><li><strong>Equality of political rights</strong>: Each race holds representative seats in the Anchor Assembly allocated by population proportion; races with smaller populations are guaranteed at least one guaranteed seat.</li><li><strong>Guarantee of cultural rights</strong>: Each race has the right to preserve and develop its own language, script, religion, customs, and cultural traditions; the symbiotic civilization has established a special fund to protect the cultures of endangered races.</li><li><strong>Equality of educational rights</strong>: Members of every race enjoy equal rights to education; the education system fully considers the physiological and cognitive characteristics of different races and provides differentiated educational programs.</li><li><strong>Equality of cultivation rights</strong>: The Three Hundred Origin Cultivation Systems are opened equally to all races; the allocation of cultivation resources fully considers the differences in physique and energy needs of different races.</li><li><strong>Guarantee of special needs</strong>: For races with special physiological needs (such as the energy-environment needs of the elemental races and the light needs of the plant races), the symbiotic civilization provides targeted safeguards in public facilities and living environments.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The Register of All Races is the concrete embodiment of the &quot;advancement of all races together&quot; ideal of the Anchor Symbiotic Civilization. From humanoid forms to consciousness forms, from material life to digital life, every race contributes irreplaceable strength to the symbiotic civilization through its unique way of existence. The Republic of Ten Thousand Races does not assimilate all races into the human race, but achieves common evolution on the basis of respecting diversity — this is precisely the fundamental reason why the symbiotic civilization surpasses predatory civilizations.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>50-万族谱系总览 (Overview of the Genealogy of All Races)</li><li>51-人族定位与特质 (Positioning and Traits of the Human Race)</li><li>77-万族共和成立 (The Founding of the Myriad Races Republic)</li></ul>',31)])])}const f=t(r,[["render",o]]);export{m as __pageData,f as default};
